package instancesearch_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/Emyrk/chronicle/internal/instancesearch"
)

// TestParseCELFrontendFixture checks the Go parser reads what the frontend's
// formatCEL writes. The fixture is generated by celFixture.test.ts from the
// same examples TestUIExamples writes.
func TestParseCELFrontendFixture(t *testing.T) {
	t.Parallel()

	path := filepath.Join("..", "..", "frontend", "chronicle", "src", "pages", "InstanceSearch", "generated", "searchExamplesCEL.json")
	raw, err := os.ReadFile(path)
	require.NoError(t, err)
	var cases []struct {
		ID    string               `json:"id"`
		Text  string               `json:"text"`
		Where *instancesearch.Node `json:"where"`
	}
	require.NoError(t, json.Unmarshal(raw, &cases))

	var examples []struct {
		ID string `json:"id"`
	}
	raw, err = os.ReadFile(filepath.Join(filepath.Dir(path), "searchExamples.json"))
	require.NoError(t, err)
	require.NoError(t, json.Unmarshal(raw, &examples))
	require.Len(t, cases, len(examples), "regenerate searchExamplesCEL.json (see celFixture.test.ts)")

	for _, c := range cases {
		got, err := instancesearch.ParseCEL(c.Text)
		require.NoError(t, err, c.ID)
		require.Equal(t, c.Where, got, c.ID)
		// The Go formatter writes the same dialect.
		got, err = instancesearch.ParseCEL(instancesearch.FormatCEL(c.Where))
		require.NoError(t, err, c.ID)
		require.Equal(t, c.Where, got, c.ID)
	}
}

func TestParseCEL(t *testing.T) {
	t.Parallel()

	pred := func(field string, op instancesearch.Op, value any) instancesearch.Node {
		return instancesearch.Node{Field: field, Op: op, Value: value}
	}
	cases := []struct {
		src  string
		want *instancesearch.Node
	}{
		{"", nil},
		{"  true ", nil},
		{`instance.name == "Molten Core"`, &instancesearch.Node{Field: "instance.name", Op: instancesearch.OpEq, Value: "Molten Core"}},
		{`players.exists(x, x.class == "MAGE")`, &instancesearch.Node{AnyPlayer: &instancesearch.Node{Field: "player.class", Op: instancesearch.OpEq, Value: "MAGE"}}},
		{`players.size() > 30 || instance.player_count <= 20`, &instancesearch.Node{Or: []instancesearch.Node{
			{CountPlayers: &instancesearch.Count{Op: instancesearch.OpGt, Value: 30}},
			pred("instance.player_count", instancesearch.OpLte, float64(20)),
		}}},
		{`!(instance.guild in ["A", "B"])`, &instancesearch.Node{Field: "instance.guild", Op: instancesearch.OpNotIn, Value: []any{"A", "B"}}},
		{`!instance.capabilities.exists(c, c in ["interrupt"])`, &instancesearch.Node{Field: "instance.capability", Op: instancesearch.OpNotIn, Value: []any{"interrupt"}}},
		{`!("server-side" in instance.capabilities)`, &instancesearch.Node{Field: "instance.capability", Op: instancesearch.OpNe, Value: "server-side"}},
		{`!(instance.name == "x")`, &instancesearch.Node{Not: &instancesearch.Node{Field: "instance.name", Op: instancesearch.OpEq, Value: "x"}}},
		{`instance.started_at >= timestamp("2026-10-01T00:00:00Z")`, &instancesearch.Node{Field: "instance.started_at", Op: instancesearch.OpGte, Value: "2026-10-01T00:00:00Z"}},
		{`instance.deaths.between(-1, 2.5)`, &instancesearch.Node{Field: "instance.deaths", Op: instancesearch.OpBetween, Value: []any{float64(-1), 2.5}}},
		{`instance.name.startsWith("Mol") && instance.guild.contains("ë")`, &instancesearch.Node{And: []instancesearch.Node{
			pred("instance.name", instancesearch.OpStartsWith, "Mol"),
			pred("instance.guild", instancesearch.OpContains, "ë"),
		}}},
		{`encounters.filter(e, e.killed == true).size() == 0`, &instancesearch.Node{CountEncounters: &instancesearch.Count{
			Op: instancesearch.OpEq, Value: 0, Where: &instancesearch.Node{Field: "encounter.killed", Op: instancesearch.OpEq, Value: true},
		}}},
		{`players.exists(p, p.sub_spec({"on": "trash"}) == "Bear" && p.parse({"bosses": ["Ragnaros"], "match": "each", "parse_scope": "realm", "metric": "hps"}) >= 95)`,
			&instancesearch.Node{AnyPlayer: &instancesearch.Node{And: []instancesearch.Node{
				{Field: "player.sub_spec", Op: instancesearch.OpEq, Value: "Bear", On: instancesearch.OnTrash},
				{Field: "player.parse", Op: instancesearch.OpGte, Value: float64(95), Bosses: []string{"Ragnaros"}, Match: instancesearch.MatchEach, ParseScope: instancesearch.ParseScopeRealm, Metric: instancesearch.MetricHPS},
			}}}},
		// Chains flatten; parentheses keep a differing group.
		{`instance.a == 1 && (instance.b == 2 || instance.c == 3) && (instance.d == 4 && instance.e == 5)`, &instancesearch.Node{And: []instancesearch.Node{
			pred("instance.a", instancesearch.OpEq, float64(1)),
			{Or: []instancesearch.Node{pred("instance.b", instancesearch.OpEq, float64(2)), pred("instance.c", instancesearch.OpEq, float64(3))}},
			pred("instance.d", instancesearch.OpEq, float64(4)),
			pred("instance.e", instancesearch.OpEq, float64(5)),
		}}},
	}
	for _, c := range cases {
		got, err := instancesearch.ParseCEL(c.src)
		require.NoError(t, err, c.src)
		require.Equal(t, c.want, got, c.src)
	}
}

func TestParseCELErrors(t *testing.T) {
	t.Parallel()

	cases := []struct {
		src    string
		msg    string
		offset int
	}{
		{`instance.name ==`, "Expected a value", 16},
		{`p.class == "MAGE"`, `Unknown name "p"`, 0},
		{`players.exists(p, players.exists(q, q.name == "x"))`, "only be used at the top level", 18},
		{`instance.name == "unterminated`, "Unterminated string", 17},
		{`instance.name == "bad \q"`, "Invalid string", 17},
		{`instance.name.endsWith("x")`, `Unknown method "endsWith"`, 14},
		{`players.any(p, p.class == "MAGE")`, `Unknown method "any"`, 8},
		{`instance.kill_time_ms({"boss": ["Rag"]}) > 0`, `Unknown option "boss"`, 22},
		{`instance.kill_time_ms({"bosses": "Rag"}) > 0`, `"bosses" must be a list`, 22},
		{`instance.name == "a" instance.realm == "b"`, "Unexpected text", 21},
		{`instance.name == "a" # x`, `Unexpected character "#"`, 21},
		// Offsets count characters, not bytes.
		{`instance.guild == "Ëlune" @`, `Unexpected character "@"`, 26},
		{`(instance.name == "a"`, `Expected ")"`, 21},
		{`instance.name == "a")`, "Unexpected text", 20},
		{`instance.name == "a" && `, "Expected a condition", 24},
		{`instance.name in "a"`, "Expected a list after in", 17},
		{`instance.name ~ "a"`, `Unexpected character "~"`, 14},
		{`instance.name "a"`, "Expected ==", 14},
		{`players.size() >= 2.5`, "Expected a whole number", 18},
		{`players.size() >= "2"`, "Expected a number", 18},
		{`instance.started_at > timestamp(5)`, "Expected a date string", 32},
		{`instance.name in ["a" "b"]`, `Expected ","`, 22},
	}
	for _, c := range cases {
		_, err := instancesearch.ParseCEL(c.src)
		var pe *instancesearch.CELParseError
		require.ErrorAs(t, err, &pe, c.src)
		require.Contains(t, pe.Message, c.msg, c.src)
		require.Equal(t, c.offset, pe.Offset, c.src)
	}
}
